import { SnapshotColumnsFigure, ColumnCombinationFigure, CancellationNullFigure, IndependentGaussianFigure, ProbeBlockShapesFigure, ObservedBasisFigure, CompressionProjectionFigure, SmallSvdLiftFigure, RankDeficientRangeFigure, NormMetricsFigure, SingularTailFloorFigure, OrthogonalLossFigure, DominantTailBlocksFigure, ExpectationVersusDrawFigure, SingularPowerFigure, StabilizedAlternationFigure, ScratchOwnerTransposeFigure, PassStorageFigure, OneViewRecoveryFigure, KrylovWorkspaceFigure, MixThenRestrictFigure, ObservationSketchFigure, DestroyedResidualFigure, ResidualEmbeddingFigure, FiniteChordsAndSubspaceFigure, LeverageRowCoordinatesFigure, SamplingRescaleFigure, PreconditionCoordinatesFigure, TraceDiagonalOperatorFigure, SignProductFigure, SignVarianceFigure, CapturedResidualTraceFigure, TraceDeflationQueriesFigure, TrainingBlindSpotFigure, AdaptiveValidationFigure, RecordedIrisObjectFigure, RecordedRangeLossFigure, LibrarySettingsFigure, ApplicationConsequencesFigure, SmootherSensitivityFigure, NystromColumnFigure, ActualRowColumnFigure, LatentNoiseObjectFigure, ValidationPracticeFigure, SketchFailurePracticeFigure, FiniteMeanPracticeFigure, OriginalObjectivePracticeFigure, TraceDeflationPracticeFigure, RecordedUnitsPracticeFigure } from '../../components/lesson-labs/RandomizedLinearAlgebraFigures.jsx';
import { WeightedColumnProbeLab, SpectralBudgetLab, PowerIterationLab, RowSketchLab, TraceEstimatorLab, FreshProbeLab, PassDecisionLab } from '../../components/lesson-labs/RandomizedLinearAlgebraFlowLabs.jsx';
import { randomizedApplications } from '../randomized-linear-algebra-application-examples.js';
import '../../components/lesson-labs/lesson-flow.css';
